python3 -c "
from PIL import Image
img = Image.open('/app/output/final_poster.png')
w, h = img.size
# Check all y positions for any non-bg pixels near right edge
issues = []
for y in range(h):
    for x in range(w-10, w):
        p = img.getpixel((x, y))
        if p != (10, 10, 13):
            issues.append((x, y, p))
            if len(issues) > 20:
                break
    if len(issues) > 20:
        break

print(f'Found {len(issues)} edge issues')
for issue in issues[:10]:
    print(issue)
"

