from PIL import Image
img = Image.open('/app/output/final_poster.png')
w, h = img.size
# The pixel at x=6817 is within margin (MARGIN=170, so w-170=6847)
# 6817 < 6847, so it's inside the content area. Let's check if any pixels are outside margin
margin = 170
issues = []
for y in range(h):
    for x in range(margin):
        p = img.getpixel((x, y))
        if p != (10, 10, 13):
            issues.append(('left', x, y, p))
            if len(issues) > 10:
                break
    for x in range(w-margin, w):
        p = img.getpixel((x, y))
        if p != (10, 10, 13):
            issues.append(('right', x, y, p))
            if len(issues) > 10:
                break
    if len(issues) > 10:
        break

print(f'Found {len(issues)} margin violations')
for issue in issues[:10]:
    print(issue)
"
